SELECT analytics_order_facts.region, COUNT(DISTINCT analytics_order_facts.order_id) AS order_count FROM analytics_order_facts WHERE analytics_order_facts.year = 2022 AND analytics_order_facts.month = 4 AND analytics_order_facts.channel = 'retail' AND analytics_order_facts.customer_segment = 'small_business' AND analytics_order_facts.category = 'category_04' AND analytics_order_facts.payment_method = 'bank_transfer' GROUP BY analytics_order_facts.region ORDER BY order_count DESC, analytics_order_facts.region ASC LIMIT 12
